 void hci_uart_init_work(struct work_struct *work)
 {
 	struct hci_uart *hu = container_of(work, struct hci_uart, init_ready);
 	int err;
 	struct hci_dev *hdev;

 	if (!test_and_clear_bit(HCI_UART_INIT_PENDING, &hu->hdev_flags))
 		return;

 	err = hci_register_dev(hu->hdev);
 	if (err < 0) {
 		BT_ERR("Can't register HCI device");
+
+		percpu_down_write(&hu->proto_lock);
 		clear_bit(HCI_UART_PROTO_READY, &hu->flags);
+		percpu_up_write(&hu->proto_lock);
+
+		/* Safely cancel work after clearing flags */
+		cancel_work_sync(&hu->write_work);
+
+		/* Close protocol before freeing hdev */
 		hu->proto->close(hu);
 		hdev = hu->hdev;
 		hu->hdev = NULL;
 		hci_free_dev(hdev);
 		return;
 	}

 	set_bit(HCI_UART_REGISTERED, &hu->flags);
 }

 /* Close device */
 static int hci_uart_close(struct hci_dev *hdev)
 {
+	struct hci_uart *hu = hci_get_drvdata(hdev);
+
 	BT_DBG("hdev %p", hdev);

+	cancel_work_sync(&hu->write_work);
+
 	hci_uart_flush(hdev);
 	hdev->flush = NULL;
 	return 0;
 }

  */
 static void hci_uart_tty_close(struct tty_struct *tty)
 {
 	struct hci_uart *hu = tty->disc_data;
 	struct hci_dev *hdev;
+	bool proto_ready;

 	BT_DBG("tty %p", tty);

 	/* Detach from the tty */
 	tty->disc_data = NULL;

 	if (!hu)
 		return;

-	hdev = hu->hdev;
-	if (hdev)
-		hci_uart_close(hdev);
+	/* Wait for init_ready to finish to prevent registration races */
+	cancel_work_sync(&hu->init_ready);

-	if (test_bit(HCI_UART_PROTO_READY, &hu->flags)) {
+	proto_ready = test_bit(HCI_UART_PROTO_READY, &hu->flags);
+	if (proto_ready) {
 		percpu_down_write(&hu->proto_lock);
 		clear_bit(HCI_UART_PROTO_READY, &hu->flags);
 		percpu_up_write(&hu->proto_lock);
+	}

-		cancel_work_sync(&hu->init_ready);
-		cancel_work_sync(&hu->write_work);
+	/*
+	 * Unconditionally cancel write_work AFTER clearing PROTO_READY.
+	 * This ensures that concurrent protocol timers cannot requeue
+	 * write_work via hci_uart_tx_wakeup(), permanently preventing
+	 * double-free races and UAFs.
+	 */
+	cancel_work_sync(&hu->write_work);
+
+	hdev = hu->hdev;
+	if (hdev)
+		hci_uart_close(hdev); /* proto->flush is safely skipped */

+	if (proto_ready) {
 		if (hdev) {
 			if (test_bit(HCI_UART_REGISTERED, &hu->flags))
 				hci_unregister_dev(hdev);
-			hci_free_dev(hdev);
 		}
+		/* Close protocol before freeing hdev (intrinsically purges queues) */
 		hu->proto->close(hu);
+
+		if (hdev)
+			hci_free_dev(hdev);
 	}
 	clear_bit(HCI_UART_PROTO_SET, &hu->flags);

 	percpu_free_rwsem(&hu->proto_lock);

 	kfree(hu);
 }

  */
 static void hci_uart_tty_receive(struct tty_struct *tty, const u8 *data,
 				 const u8 *flags, size_t count)
 {
 	struct hci_uart *hu = tty->disc_data;

 	if (!hu || tty != hu->tty)
 		return;

 	percpu_down_read(&hu->proto_lock);

 	if (!test_bit(HCI_UART_PROTO_READY, &hu->flags) &&
 	    !test_bit(HCI_UART_PROTO_INIT, &hu->flags)) {
 		percpu_up_read(&hu->proto_lock);
 		return;
 	}

 	/* It does not need a lock here as it is already protected by a mutex in
 	 * tty caller
 	 */
 	hu->proto->recv(hu, data, count);
-	percpu_up_read(&hu->proto_lock);

 	if (hu->hdev)
 		hu->hdev->stat.byte_rx += count;

+	percpu_up_read(&hu->proto_lock);
+
 	tty_unthrottle(tty);
 }

 static int hci_uart_register_dev(struct hci_uart *hu)
 {
 	struct hci_dev *hdev;
 	int err;

 	BT_DBG("");

 	/* Initialize and register HCI device */
 	hdev = hci_alloc_dev();
 	if (!hdev) {
 		BT_ERR("Can't allocate HCI device");
 		return -ENOMEM;
 	}

 	hu->hdev = hdev;

 	hdev->bus = HCI_UART;
 	hci_set_drvdata(hdev, hu);

 	/* Only when vendor specific setup callback is provided, consider
 	 * the manufacturer information valid. This avoids filling in the
 	 * value for Ericsson when nothing is specified.
 	 */
 	if (hu->proto->setup)
 		hdev->manufacturer = hu->proto->manufacturer;

 	hdev->open  = hci_uart_open;
 	hdev->close = hci_uart_close;
 	hdev->flush = hci_uart_flush;
 	hdev->send  = hci_uart_send_frame;
 	hdev->setup = hci_uart_setup;
 	SET_HCIDEV_DEV(hdev, hu->tty->dev);

 	if (test_bit(HCI_UART_RAW_DEVICE, &hu->hdev_flags))
 		hci_set_quirk(hdev, HCI_QUIRK_RAW_DEVICE);

 	if (test_bit(HCI_UART_EXT_CONFIG, &hu->hdev_flags))
 		hci_set_quirk(hdev, HCI_QUIRK_EXTERNAL_CONFIG);

 	if (!test_bit(HCI_UART_RESET_ON_INIT, &hu->hdev_flags))
 		hci_set_quirk(hdev, HCI_QUIRK_RESET_ON_CLOSE);

 	/* Only call open() for the protocol after hdev is fully initialized as
 	 * open() (or a timer/workqueue it starts) may attempt to reference it.
 	 */
 	err = hu->proto->open(hu);
 	if (err) {
 		hu->hdev = NULL;
 		hci_free_dev(hdev);
 		return err;
 	}

 	set_bit(HCI_UART_PROTO_INIT, &hu->flags);

 	if (test_bit(HCI_UART_INIT_PENDING, &hu->hdev_flags))
 		return 0;

 	if (hci_register_dev(hdev) < 0) {
 		BT_ERR("Can't register HCI device");
 		percpu_down_write(&hu->proto_lock);
 		clear_bit(HCI_UART_PROTO_INIT, &hu->flags);
 		percpu_up_write(&hu->proto_lock);
+		/* Cancel work after clearing flags */
+		cancel_work_sync(&hu->write_work);
+
+		/* Close protocol before freeing hdev */
 		hu->proto->close(hu);
 		hu->hdev = NULL;
 		hci_free_dev(hdev);
 		return -ENODEV;
 	}

 	set_bit(HCI_UART_REGISTERED, &hu->flags);

 	return 0;
 }



